#!/usr/bin/env python3
# File: lvgl_assets.py
# Spec: design rnd-disp 4.3; Task B3-3b.
# Description: Generate an original RGB565 S3 mark using only Python's standard library.
# Clock domain: host generator; generated const data is linked into DDR.
"""Generate the S3 menu image; all generated files belong under build/."""
import argparse
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    pixels = []
    for y in range(64):
        for x in range(64):
            r, g, b = 12 + x, 30 + y * 2, 65 + x + y
            if (12 <= x < 25 and 14 <= y < 50) or (25 <= x < 51 and 14 <= y < 25):
                r, g, b = 60, 226, 180
            pixels.append(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3))
    lines = ["/* Generated by tools/s3/lvgl_assets.py; original project artwork. */",
             '#include "lvgl.h"',
             "static const _Alignas(64) uint16_t pixels[4096] = {"]
    lines.extend("    " + ", ".join(f"0x{p:04x}" for p in pixels[i:i + 12]) + ","
                 for i in range(0, len(pixels), 12))
    lines += ["};", "const lv_image_dsc_t s3_lvgl_mark = {",
              "    .header = { .magic = LV_IMAGE_HEADER_MAGIC, .cf = LV_COLOR_FORMAT_RGB565,",
              "                .w = 64, .h = 64, .stride = 128 },",
              "    .data_size = sizeof(pixels), .data = (const uint8_t *)pixels", "};", ""]
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text("\n".join(lines))


if __name__ == "__main__":
    main()
